function t(string $s): string { return (($GLOBALS['LANG'] ?? 'en') === 'bn' && isset($GLOBALS['BN'][$s])) ? $GLOBALS['BN'][$s] : $s; }
function status_label(string $s): string { return t(ucfirst(str_replace('_', ' ', $s))); }
function fdate(?string $ts, bool $time = true): string {
  if (!$ts) return '-'; $d = strtotime($ts); $s = date($time ? 'd M Y, h:i A' : 'd M Y', $d);
  if (($GLOBALS['LANG'] ?? 'en') !== 'bn') return $s;
  $m = ['Jan' => 'জানু', 'Feb' => 'ফেব', 'Mar' => 'মার্চ', 'Apr' => 'এপ্রি', 'May' => 'মে', 'Jun' => 'জুন', 'Jul' => 'জুল', 'Aug' => 'আগ', 'Sep' => 'সেপ্টে', 'Oct' => 'অক্টো', 'Nov' => 'নভে', 'Dec' => 'ডিসে', 'AM' => 'পূর্বাহ্ণ', 'PM' => 'অপরাহ্ণ'];
  $s = strtr($s, $m); return strtr($s, ['0' => '০', '1' => '১', '2' => '২', '3' => '৩', '4' => '৪', '5' => '৫', '6' => '৬', '7' => '৭', '8' => '৮', '9' => '৯']);
}
